// The adapter for Prisma 7 (`@sqlane/core/adapter-prisma`): `enqueue` takes a Prisma client or the client of an
// interactive transaction. The SQL of sqlane runs through `$queryRawUnsafe` and `$executeRawUnsafe`, with the
// placeholders of the database (`?`, `$1`). No import of Prisma (its client is generated by the app): the adapter uses
// the client that it gets. Prisma has no connection outside a transaction, so `withConnection` (the migration) runs
// in one; and no after-commit hook: after an enqueue in a transaction, sqlane re-probes.
import { ConfigError } from '../errors.js';

/** Marks the client of an interactive transaction; only to wake at once after an enqueue in a transaction of its own */
const TRANSACTION_SCOPE = Symbol.for('prisma.client.transaction.scope_context');
/** The migration: its lock wait is bounded by `lockTimeout`, its DDL is short */
const CONNECTION_TIMEOUT_MS = 60 * 60_000;
/** A queue transaction: a claim or the write of a result, a few statements */
const QUEUE_TRANSACTION_TIMEOUT_MS = 60_000;
/** Waiting for a connection of Prisma's pool */
const MAX_WAIT_MS = 10_000;

/**
 * A Prisma client or the client of an interactive transaction, as far as the adapter reads it.
 * @typedef {object} PrismaClientLike
 * @property {(sql: string, ...params: unknown[]) => Promise<unknown>} $queryRawUnsafe
 * @property {(sql: string, ...params: unknown[]) => Promise<number>} $executeRawUnsafe
 * @property {(func: (tx: any) => Promise<any>, options?: object) => Promise<any>} $transaction
 */

/**
 * @typedef {object} PrismaAdapterOptions
 * @property {import('../types.js').Dialect} dialect The database of the client: Prisma tells it in no public API.
 */

/**
 * @param {PrismaClientLike} client
 * @returns {import('../types.js').Executor}
 */
function executorOf(client) {
    return {
        query: async (sql, params) => {
            const rows = await client.$queryRawUnsafe(sql, ...params);

            return Array.isArray(rows) ? rows : [];
        },
        run: async (sql, params) => Number(await client.$executeRawUnsafe(sql, ...params)),
    };
}

/**
 * @param {unknown} client
 * @returns {boolean} It has what the adapter uses.
 */
function isPrismaClient(client) {
    const candidate = /** @type {Record<string, unknown> | null | undefined} */ (client);

    return ['$queryRawUnsafe', '$executeRawUnsafe', '$transaction']
        .every(method => typeof candidate?.[method] === 'function');
}

/**
 * The adapter for Prisma 7 (MySQL or PostgreSQL). `enqueue` then takes a Prisma client (a transaction of its own) or
 * the client of an interactive transaction (the caller's: the job commits with it).
 * @param {PrismaClientLike} prisma The queue's own Prisma client: claims, leases, results.
 * @param {PrismaAdapterOptions} options
 * @returns {import('../types.js').Adapter<PrismaClientLike>}
 */
export function prismaAdapter(prisma, options) {
    if (!isPrismaClient(prisma)) {
        throw new ConfigError('prismaAdapter: expects a Prisma client (Prisma 7)');
    }

    const dialect = options?.dialect;

    if (dialect !== 'mysql' && dialect !== 'mariadb' && dialect !== 'postgres') {
        throw new ConfigError('prismaAdapter: "dialect" must be "mysql", "mariadb" or "postgres"');
    }

    return {
        dialect,
        wrap: executorOf,
        queue: executorOf(prisma),
        withConnection: func => prisma.$transaction(tx => func(executorOf(tx)), {
            timeout: CONNECTION_TIMEOUT_MS,
            maxWait: MAX_WAIT_MS,
        }),
        transactionalConnection: true,
        queueTransaction: func => prisma.$transaction(tx => func(executorOf(tx)), {
            isolationLevel: 'ReadCommitted',
            timeout: QUEUE_TRANSACTION_TIMEOUT_MS,
            maxWait: MAX_WAIT_MS,
        }),
        // A client: a transaction of its own. The client of a transaction: its nested `$transaction` joins it.
        inTransaction: (connection, func) => connection.$transaction(
            tx => func(executorOf(tx)),
            { maxWait: MAX_WAIT_MS },
        ),
        afterCommit: (connection, onCommit) => {
            if (TRANSACTION_SCOPE in connection) {
                return false;
            }

            onCommit();

            return true;
        },
    };
}
